-- PT102-S2-Q8. Batch 07.
BEGIN;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch07$PT102-S2-Q8$batch07$ AND q.stimulus=$batch07$Toddlers are not being malicious when they bite people. For example, a child may want a toy, and feel that the person he or she bites is preventing him or her from having it.$batch07$ AND q.prompt=$batch07$The situation as described above most closely conforms to which one of the following generalizations?$batch07$ AND q.correct_choice=$batch07$A$batch07$) THEN RAISE EXCEPTION 'Question changed: PT102-S2-Q8'; END IF; END $guard$;
DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id WHERE q.qid=$batch07$PT102-S2-Q8$batch07$ AND e.style IN ('single','standard')) <> 0 THEN RAISE EXCEPTION 'Explanation row changed: PT102-S2-Q8'; END IF; END $guard$;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch07$PT102-S2-Q8$batch07$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch07$Statements$batch07$, $batch07$Toddlers who bite aren't being malicious. Example: a child wants a toy and feels the person they bite is keeping it from them.$batch07$), (1, $batch07$Evaluate$batch07$, $batch07$Pause and infer. The example gives the biting a purpose: there is an obstacle (someone in the way of the toy), and the bite is the toddler's way of dealing with it. That is problem-solving, crude as it is. Notice what the passage does *not* say: whether biting gets the toddler the toy.$batch07$), (2, $batch07$Goal$batch07$, $batch07$Something weak like "toddlers sometimes bite to deal with an obstacle." Watch for answers that say biting *works*.$batch07$)) v(position,label,body) WHERE q.qid=$batch07$PT102-S2-Q8$batch07$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch07$A$batch07$, $batch07$The toddler wants the toy, sees a person blocking it, and bites. That is an attempt to solve a problem. "Sometimes" and "try to" keep the claim as small as the example.$batch07$), ($batch07$B$batch07$, $batch07$The example is about a toy, not getting adults' attention.$batch07$), ($batch07$C$batch07$, $batch07$Nothing in the passage tells us what toddlers believe adults think about biting.$batch07$), ($batch07$D$batch07$, $batch07$We have no information on whether biting thwarts toddlers' goals, or whether toddlers realize it.$batch07$), ($batch07$E$batch07$, $batch07$This is the most popular wrong answer, and it shows the gap between *trying* and *succeeding*. The passage tells us why the toddler bites. It never says the toddler gets the toy. Biting could fail every single time and the passage would still be true. A only claims an attempt; E claims a result.$batch07$)) v(letter,body) WHERE q.qid=$batch07$PT102-S2-Q8$batch07$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
COMMIT;
